function ScalarSetting({item,value,status,onSave}){
  const[key,kind,restart]=item;
  const shown=value==null?"":String(value);
  const[draft,setDraft]=React.useState(shown);
  const[visible,setVisible]=React.useState(false);
  React.useEffect(()=>{setDraft(shown)},[shown]);
  // text fields save shortly after you stop typing
  React.useEffect(()=>{
    if(kind!=="string"&&kind!=="secret"&&kind!=="int")return;
    if(draft===shown)return;
    if(kind==="int"&&!/^\d+$/.test(draft.trim()))return;
    const timer=setTimeout(()=>onSave(key,kind==="int"?Number(draft.trim()):draft.trim()),900);
    return ()=>clearTimeout(timer);
  },[draft]);

  let control;
  if(kind==="bool")control=jsx.jsx(UI.Toggle,{value:!!value,onChange:checked=>onSave(key,checked)});
  else if(kind==="level"||kind==="lang"){
    const options=kind==="level"
      ?[0,1,2,3,4,5,6].map(n=>({data:n,label:st("lvl"+n)}))
      :STEAM_LANGS.concat(STEAM_LANGS.includes(shown)||!shown?[]:[shown]).map(v=>({data:v,label:v}));
    control=jsx.jsx("div",{style:{width:"100%",maxWidth:"320px"},children:jsx.jsx(UI.Dropdown,{rgOptions:options,selectedOption:kind==="level"?Number(value):shown,onChange:option=>onSave(key,option.data)})});
  }else{
    const field=jsx.jsx(UI.TextField,{value:draft,bIsPassword:kind==="secret"&&!visible,onChange:e=>setDraft(kind==="int"?e.target.value.replace(/[^\d]/g,""):e.target.value)});
    control=jsx.jsxs("div",{style:{display:"flex",flexWrap:"wrap",alignItems:"center",gap:"8px",width:"100%",maxWidth:kind==="int"?"200px":"100%"},children:[
      jsx.jsx("div",{style:{flex:"1 1 160px",minWidth:0},children:field}),
      kind==="secret"?jsx.jsx(UI.Button,{style:{width:"auto",minWidth:"90px",flex:"0 0 auto"},onClick:()=>setVisible(!visible),children:st(visible?"hide":"show")}):null,
    ]});
  }
  const below=kind!=="bool";
  return jsx.jsx(UI.Field,{label:st(key)[0],description:describe(key,restart,status),bottomSeparator:"standard",childrenLayout:below?"below":"inline",children:control});
}

function toText(kind,entries){
  return (entries||[]).map(entry=>{
    if(kind==="ids")return String(entry);
    if(kind==="dlc_map")return entry[0]+" / "+entry[1]+" = "+entry[2];
    return entry[0]+" = "+entry[1];
  }).join("\n");
}

function fromText(kind,text){
  const entries=[];
  const lines=text.split(/\r?\n/);
  for(let index=0;index<lines.length;index++){
    const line=lines[index].trim();
    if(!line)continue;
    const fail=reason=>({error:st("lineError",{line:index+1,error:st(reason)})});
    if(kind==="ids"){if(!/^\d+$/.test(line))return fail("errNumber");entries.push(line);continue}
    if(kind==="dlc_map"){
      const m=line.match(/^(\d+)\s*\/\s*(\d+)\s*=\s*(.*)$/);
      if(!m)return fail("errFormat");
      entries.push([m[1],m[2],m[3].trim()]);continue;
    }
    const at=line.indexOf("=");
    if(at<0)return fail("errFormat");
    const left=line.slice(0,at).trim(),right=line.slice(at+1).trim();
    if(!/^\d+$/.test(left))return fail("errNumber");
    if(kind==="num_map"&&!/^\d+$/.test(right))return fail("errNumber");
    if(kind==="owner_map"&&!/^\d+(\s*,\s*\d+)*$/.test(right))return fail("errNumber");
    entries.push([left,right]);
  }
  return {entries};
}

function ListSetting({item,list,status,onSave}){
  const[key]=item;
  const kind=list.kind;
  const entries=Array.isArray(list.entries)?list.entries:[];
  const[open,setOpen]=React.useState(false);
  const[draft,setDraft]=React.useState("");
  const[error,setError]=React.useState("");
  const toggle=()=>{if(!open){setDraft(toText(kind,entries));setError("")}setOpen(!open)};
  const save=async()=>{
    const parsed=fromText(kind,draft);
    if(parsed.error){setError(parsed.error);return}
    setError("");
    if(await onSave(key,parsed.entries))setOpen(false);
  };
  const summary=entries.length?st("entries",{n:entries.length}):st("empty");
  return jsx.jsxs("div",{children:[
    jsx.jsx(UI.Field,{label:st(key)[0],description:describe(key,false,status),bottomSeparator:open?"none":"standard",childrenLayout:"below",children:
      jsx.jsxs("div",{style:{display:"flex",alignItems:"center",gap:"10px",minWidth:0},children:[
        jsx.jsx(UI.Button,{style:{width:"auto",minWidth:"110px",flex:"0 0 auto"},onClick:toggle,children:st(open?"close":"edit")}),
        jsx.jsx("span",{style:{fontSize:"12px",color:"#8f98a0",flex:"0 0 auto"},children:summary}),
        !open&&entries.length?jsx.jsx("span",{style:{...codeStyle,flex:"1 1 auto",minWidth:0,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",wordBreak:"normal"},
          children:toText(kind,entries.slice(0,4)).split(String.fromCharCode(10)).join("  ·  ")+(entries.length>4?"  …":"")}):null,
      ]})}),
    open?jsx.jsxs("div",{style:{padding:"4px 0 14px",borderBottom:"1px solid rgba(255,255,255,.08)"},children:[
      jsx.jsx("textarea",{value:draft,spellCheck:false,placeholder:EXAMPLES[key]||"",style:textareaStyle,onChange:e=>setDraft(e.target.value)}),
      jsx.jsxs("div",{style:{display:"flex",flexWrap:"wrap",alignItems:"center",gap:"12px",paddingTop:"8px"},children:[
        jsx.jsx("div",{style:{flex:"1 1 180px",minWidth:0,fontSize:"12px",color:error?"#d9534f":"#8f98a0"},children:error||st("fmt_"+kind)}),
        jsx.jsx(UI.Button,{style:{width:"auto",minWidth:"120px",flex:"0 0 auto"},onClick:save,children:st("save")}),
      ]}),
    ]}):null,
  ]});
}

function StatusSetting({item,list,status,onSave}){
  const[key]=item;
  const entries=Array.isArray(list.entries)?list.entries:[];
  const get=name=>{const found=entries.find(e=>e[0]===name);return found?String(found[1]):""};
  const[appId,setAppId]=React.useState(get("AppId")||"0");
  const[title,setTitle]=React.useState(get("Title"));
  const save=()=>onSave(key,[["AppId",appId||"0"],["Title",title]]);
  return jsx.jsx(UI.Field,{label:st(key)[0],description:describe(key,false,status),bottomSeparator:"standard",childrenLayout:"below",children:
    jsx.jsxs("div",{style:{display:"flex",alignItems:"flex-end",gap:"10px",flexWrap:"wrap"},children:[
      jsx.jsxs("div",{style:{flex:"0 1 140px",minWidth:"90px"},children:[
        jsx.jsx("div",{style:{fontSize:"12px",color:"#8f98a0",paddingBottom:"4px"},children:st("statusAppId")}),
        jsx.jsx(UI.TextField,{value:appId,onChange:e=>setAppId(e.target.value.replace(/[^\d]/g,""))})]}),
      jsx.jsxs("div",{style:{flex:"1 1 160px",minWidth:0},children:[
        jsx.jsx("div",{style:{fontSize:"12px",color:"#8f98a0",paddingBottom:"4px"},children:st("statusTitle")}),
        jsx.jsx(UI.TextField,{value:title,onChange:e=>setTitle(e.target.value)})]}),
      jsx.jsx(UI.Button,{style:{width:"auto",minWidth:"120px"},onClick:save,children:st("save")}),
    ]})});
}

function ToolSettings(){
  const[values,setValues]=React.useState(null);
  const[lists,setLists]=React.useState(null);
  const[error,setError]=React.useState("");
  const[status,setStatus]=React.useState({});

  const load=async()=>{
    try{
      const res=JSON.parse(await getToolSettings());
      const resLists=JSON.parse(await getToolLists());
      if(res.success&&resLists.success){setValues(res.values||{});setLists(resLists.lists||{});setError("")}
      else setError(res.error||resLists.error||"error");
    }catch(err){setError(String(err))}
  };
  React.useEffect(()=>{load()},[]);

  const flash=(key,ok,text)=>{
    setStatus(s=>({...s,[key]:{ok,text}}));
    setTimeout(()=>setStatus(s=>{const n={...s};delete n[key];return n}),ok?2500:6000);
  };

  const saveScalar=async(key,value)=>{
    setValues(v=>({...v,[key]:value}));
    try{
      const res=JSON.parse(await setToolSetting({key,value}));
      if(res.success)flash(key,true,st("settingSaved"));
      else{flash(key,false,res.error||"error");load()}
    }catch(err){flash(key,false,String(err));load()}
  };

  const saveList=async(key,entries)=>{
    try{
      const res=JSON.parse(await setToolList({key,entries:JSON.stringify(entries)}));
      if(res.success){
        setLists(l=>({...l,[key]:{...l[key],entries}}));
        flash(key,true,st("settingSaved"));
        return true;
      }
      flash(key,false,res.error||"error");
    }catch(err){flash(key,false,String(err))}
    return false;
  };

  if(error)return jsx.jsx(Line,{color:"#d9534f",children:error});
  if(!values||!lists)return null;

  const render=item=>{
    const[key,kind]=item;
    if(kind==="list")return lists[key]?jsx.jsx(ListSetting,{item,list:lists[key],status:status[key],onSave:saveList},key):null;
    if(kind==="status")return lists[key]?jsx.jsx(StatusSetting,{item,list:lists[key],status:status[key],onSave:saveList},key):null;
    return key in values?jsx.jsx(ScalarSetting,{item,value:values[key],status:status[key],onSave:saveScalar},key):null;
  };

  return jsx.jsxs("div",{style:{paddingTop:"10px"},children:[
    jsx.jsx("div",{style:{fontSize:"18px",color:"#ffffff",padding:"18px 0 4px"},children:st("settingsTitle")}),
    jsx.jsx(Line,{children:st("settingsIntro")}),
    ...TOOL_GROUPS.map(([group,items])=>jsx.jsxs("div",{children:[
      jsx.jsx("div",{style:sectionStyle,children:st(group)}),
      ...items.map(render),
    ]},group)),
  ]});
}

