function bt(key,vars){
  const own=BYID_STRINGS[lang()];
  let value=(own&&own[key])||BYID_STRINGS.english[key]||key;
  if(vars)for(const name of Object.keys(vars))value=value.replace("{"+name+"}",vars[name]);
  return value;
}

function AddById(){
  const[appId,setAppId]=React.useState("");
  const[busy,setBusy]=React.useState(false);
  const[notice,setNotice]=React.useState(null);

  const run=async mode=>{
    if(busy)return;
    const id=appId.trim();
    if(!/^\d+$/.test(id)){setNotice({ok:false,text:bt("byIdInvalid")});return}
    setBusy(true);
    setNotice({ok:true,text:bt(mode==="add"?"byIdAdding":"byIdRemoving")});
    try{
      const call=mode==="add"?addGameById:deleteGameById;
      const res=JSON.parse(await call({app_id:Number(id)}));
      if(res.success){
        const apps=(res.apps&&res.apps.length?res.apps:[res.appId||id]).join(", ");
        setNotice({ok:true,text:bt(mode==="add"?"byIdAdded":"byIdRemoved",{apps})});
        setAppId("");
        Library.refresh();
      }else setNotice({ok:false,text:res.error||"error"});
    }catch(err){setNotice({ok:false,text:String(err)})}
    setBusy(false);
  };

  return jsx.jsx(UI.Field,{label:bt("byIdTitle"),description:jsx.jsxs(jsx.Fragment,{children:[
      bt("byIdHint"),
      notice?jsx.jsx("div",{style:{color:notice.ok?"#a4d007":"#d9534f",paddingTop:"3px"},children:notice.text}):null]}),
    bottomSeparator:"standard",childrenLayout:"below",children:
    jsx.jsxs("div",{style:{display:"flex",flexWrap:"wrap",alignItems:"center",gap:"8px"},children:[
      jsx.jsx("div",{style:{flex:"1 1 160px",minWidth:0},children:jsx.jsx(UI.TextField,{value:appId,disabled:busy,placeholder:bt("byIdPlaceholder"),
        onChange:e=>setAppId(e.target.value.replace(/[^\d]/g,"")),onKeyDown:e=>{if(e.key==="Enter")run("add")}})}),
      jsx.jsx(UI.Button,{style:{width:"auto",minWidth:"110px",flex:"0 0 auto"},disabled:busy,onClick:()=>run("add"),children:bt("byIdAdd")}),
      jsx.jsx(UI.Button,{style:{width:"auto",minWidth:"110px",flex:"0 0 auto"},disabled:busy,onClick:()=>run("remove"),children:bt("byIdRemove")}),
    ]})});
}

